contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params:
    // tokenIds and tokenWeights are passed as arrays; proof consists of proof bytes32[] and flags bool[] packed in calldata via memory structs
    // We also pass baseTokenAmount to forward as msg.value when calling buy (for pools with baseToken == address(0)).
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 baseTokenAmount) public payable {
        require(tokenIds.length == tokenWeights.length, "len");

        // Build MerkleMultiProof in memory to pass to buy
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        // Observe before-values
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforeVirtualNft = c.virtualNftReserves();
        uint256 beforeBalance = address(c).balance;

        // Try calling buy with provided ETH amount (must ensure this contract has enough balance)
        // If baseToken == address(0), buy is payable; otherwise sending ETH should cause InvalidEthAmount revert inside buy.
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Ensure the test contract has the ETH to forward when needed
        if (baseTokenAmount > 0) {
            require(address(this).balance >= baseTokenAmount, "not enough eth");
        }

        try c.buy{value: baseTokenAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();
        uint256 afterBalance = address(c).balance;

        // General invariant to assert:
        // - If buy succeeded (not reverted):
        //     virtualBaseTokenReserves increased by at least (netInputAmount - feeAmount - protocolFeeAmount)
        //     virtualNftReserves decreased by sum(tokenWeights)
        //     If pool uses ETH (baseToken == address(0)) then contract balance increased by netInputAmount (since netInput includes royalties added inside buy)
        // - If buy reverted: then either merkle proof invalid or invalid ETH amount; we cannot directly detect which, but we assert that when reverted, observable reserves did not change.

        // compute sum of weights safely
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        address poolBaseToken = c.baseToken();

        if (!reverted) {
            // virtualBaseTokenReserves increased by exactly netInputAmount - feeAmount - protocolFeeAmount (as per code: virtualBaseTokenReserves += netInputAmount - fee - protocolFee)
            // We assert >= to avoid relying on exact arithmetic if unexpected rounding differs; but rule should catch bugs if not increased.
            assert(afterVirtualBase >= beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount));

            // virtualNftReserves decreased by sumWeights
            // Since virtualNftReserves is uint128, check that before >= after and difference equals sumWeights
            if (beforeVirtualNft >= afterVirtualNft) {
                assert(beforeVirtualNft - afterVirtualNft == sumWeights);
            } else {
                // should not happen, ensure false to fail if it does
                assert(false);
            }

            // ETH movement: if pool expects ETH (baseToken == address(0)), then the pool's balance must have increased by netInputAmount
            if (poolBaseToken == address(0)) {
                // afterBalance should be at least beforeBalance + netInputAmount - note buy may forward protocolFee to factory immediately, but netInputAmount includes royalty sums added before transfer
                assert(afterBalance >= beforeBalance + netInputAmount - protocolFeeAmount);
            } else {
                // If baseToken is ERC20, ETH balance shouldn't increase due to buy (unless other flows); so assert equality
                assert(afterBalance == beforeBalance);
            }
        } else {
            // If reverted, publicly observable storage should be unchanged
            assert(afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft && afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take arrays and an ETH amount to forward if needed.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 baseTokenAmount) public payable {
        require(tokenIds.length == tokenWeights.length, "len");
        // Build MerkleMultiProof in memory
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        // Observe before-values
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforeVirtualNft = c.virtualNftReserves();
        uint256 beforeBalance = address(c).balance;
        address poolBaseToken = c.baseToken();

        // ensure test contract has ETH to forward when requested
        if (baseTokenAmount > 0) {
            require(address(this).balance >= baseTokenAmount, "not enough eth");
        }

        // Attempt the call at top-level (must be a top-level statement). Capture revert via try/catch.
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        try c.buy{value: baseTokenAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();
        uint256 afterBalance = address(c).balance;

        // compute sumWeights (safe in memory loop)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // Single assert encoding the general rule:
        // If reverted => reserves and ETH balance unchanged.
        // If not reverted => virtualBase increased by exactly (netInput - fee - protocolFee) and virtualNft decreased by sumWeights,
        // and ETH balance behavior: if pool uses ETH then afterBalance >= beforeBalance + netInputAmount - protocolFeeAmount (protocol fee may be forwarded), else ETH balance unchanged.
        assert(
            (reverted && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft && afterBalance == beforeBalance)
            || (
                !reverted
                && afterVirtualBase >= beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount)
                && beforeVirtualNft >= afterVirtualNft
                && (beforeVirtualNft - afterVirtualNft == sumWeights)
                && (
                    (poolBaseToken == address(0) && afterBalance >= beforeBalance + netInputAmount - protocolFeeAmount)
                    || (poolBaseToken != address(0) && afterBalance == beforeBalance)
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test deposit with ETH only; require baseTokenAmount fits in uint256 and arrays lengths reasonable
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount) public payable {
        // limit size to keep loops bounded for the prover
        require(tokenIds.length <= 8, "len");
        // If forwarding ETH, ensure this contract has it available
        if (baseTokenAmount > 0) require(address(this).balance >= baseTokenAmount, "funds");

        // Observe before values
        uint256 beforeNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 beforeEthBalance = address(c).balance;
        address poolBase = c.baseToken();

        // Prepare tokenWeights/proof unused by deposit

        bool reverted;
        try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 afterEthBalance = address(c).balance;

        // If pool uses ETH (baseToken == address(0)) then a successful deposit must increase pool ETH balance by baseTokenAmount.
        // In all cases a successful deposit must increase the pool's NFT balance by tokenIds.length.
        // If call reverted then observed balances must be unchanged.
        assert(
            (reverted && afterNftBalance == beforeNftBalance && afterEthBalance == beforeEthBalance)
            || (
                !reverted
                && afterNftBalance == beforeNftBalance + tokenIds.length
                && (
                    (poolBase == address(0) && afterEthBalance == beforeEthBalance + baseTokenAmount)
                    || (poolBase != address(0) && afterEthBalance == beforeEthBalance)
                )
            )
        );
    }

    receive() external payable {}
}

