contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry for property-based fuzzing
    // params chosen to drive initialize and observe behavior
    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public payable {
        // Preconditions: none on inputs; feeRate may be any uint16

        // Read initial initialized flag
        bool wasInitializedBefore = c.initialized();

        // We must call initialize as a top-level call that may change state
        bool firstReverted;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Observe after-call values
        bool initializedAfter = c.initialized();
        uint16 observedFeeRate = c.feeRate();

        // Now attempt to call initialize a second time to check AlreadyInitialized behavior
        bool secondReverted;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule asserted:
        // 1) If contract was already initialized before our first call, the first call must revert,
        //    and initialized flag remains true.
        // 2) If it was not initialized before and feeRate > 5000, initialize must revert and initialized stays false.
        // 3) If it was not initialized before and feeRate <= 5000, initialize must succeed, initialized becomes true,
        //    and the stored feeRate equals the provided feeRate; a subsequent initialize must revert.
        assert(
            (
                wasInitializedBefore && firstReverted && initializedAfter && observedFeeRate == c.feeRate()
            ) || (
                !wasInitializedBefore && feeRate > 5000 && firstReverted && !initializedAfter
            ) || (
                !wasInitializedBefore && feeRate <= 5000 && !firstReverted && initializedAfter && observedFeeRate == feeRate && secondReverted
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry for property-based fuzzing
    // We drive buy(...) and check how virtual reserves change or that they stay the same on revert.
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofProof,
        bool[] calldata proofFlags
    ) public payable {
        // Precondition: arrays must have same length and non-empty to be meaningful
        require(tokenIds.length == tokenWeights.length);
        require(tokenIds.length > 0);

        // Read before-values
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();
        uint256 beforeBalance = address(c).balance;

        // Build MerkleMultiProof struct in memory
        C.MerkleMultiProof memory mp;
        mp.proof = proofProof;
        mp.flags = proofFlags;

        // Call buy; it may revert. Capture revert flag and any returned values via try/catch.
        bool didRevert;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: 0}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            didRevert = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            didRevert = true;
        }

        // Read after-values
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 afterBalance = address(c).balance;

        // Compute sum of weights (as uint256 to avoid overflow in solidity assert expression)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // General rule asserted:
        // - If buy reverted, reserves and contract balance must be unchanged.
        // - If buy succeeded (didRevert == false), virtualNftReserves must have decreased by exactly sumWeights,
        //   and virtualBaseTokenReserves must have increased by at least (netInputAmount - feeAmount - protocolFeeAmount).
        //   Additionally, contract balance must reflect that net payment was transferred in when baseToken==address(0) or may be unchanged otherwise;
        //   we conservatively assert that virtual reserves move in the expected directions when buy succeeded.
        assert(
            (didRevert && afterVirtualBase == beforeVirtualBase && afterVirtualNft == beforeVirtualNft && afterBalance == beforeBalance)
            || (
                !didRevert
                && afterVirtualNft + sumWeights == beforeVirtualNft
                && afterVirtualBase >= beforeVirtualBase + uint128(netInputAmount >= feeAmount + protocolFeeAmount ? (netInputAmount - feeAmount - protocolFeeAmount) : 0)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for property-based fuzzing
    // We test setFeeRate(uint16) behavior: it must revert if >5000, otherwise it must set the on-chain feeRate.
    function run(uint16 newFeeRate) public payable {
        // no precondition on c state; newFeeRate is the only input
        // read before
        uint16 before = c.feeRate();

        bool didRevert;
        // call setFeeRate and capture revert
        try c.setFeeRate(newFeeRate) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint16 after = c.feeRate();

        // General rule: if newFeeRate > 5000 the call must revert (so feeRate unchanged),
        // otherwise it must succeed and feeRate must equal newFeeRate.
        assert(
            (newFeeRate > 5000 && didRevert && after == before)
            || (newFeeRate <= 5000 && !didRevert && after == newFeeRate)
        );
    }

    receive() external payable {}
}

